(()=>{const r=[["hvezda","Hv\u011Bzda","Co ti pom\xE1h\xE1 znovu naj\xEDt klid a sm\u011Br?"],["slunce","Slunce","Kterou jednoduchou radost si dnes m\u016F\u017Ee\u0161 dop\u0159\xE1t?"],["soud","Soud","Na kterou zku\u0161enost se dnes m\u016F\u017Ee\u0161 pod\xEDvat s odstupem?"]];document.addEventListener("click",d=>{const t=d.target.closest('[data-action="flipCard"][data-preview-card]');if(!t)return;const a=r[Number(t.dataset.previewCard)];if(!a)return;const[n,e,o]=a,s=t.querySelector("img");s.src=`/img/tarot-v2/tarot_${n}.webp`,s.alt=e,t.classList.add("flipped"),t.setAttribute("aria-label",`${e}: ${o}`),document.getElementById("tarot-demo-caption").textContent=`${e} \u2014 ${o} Toto je uk\xE1zka, vlastn\xED kartu si vyt\xE1hne\u0161 v n\xE1stroji.`});})();
